// ───────────────────────── допоміжні: текст і числа ─────────────────────────
function inv_ord(string $c): int {
    $n = strlen($c); $o = ord($c[0]);
    if ($n === 1) return $o;
    if ($n === 2) return (($o & 0x1F) << 6) | (ord($c[1]) & 0x3F);
    if ($n === 3) return (($o & 0x0F) << 12) | ((ord($c[1]) & 0x3F) << 6) | (ord($c[2]) & 0x3F);
    return (($o & 0x07) << 18) | ((ord($c[1]) & 0x3F) << 12) | ((ord($c[2]) & 0x3F) << 6) | (ord($c[3]) & 0x3F);
}
function inv_chars(string $s): array {
    return preg_match_all('/./us', $s, $m) ? array_map('inv_ord', $m[0]) : [];
}
function inv_utf16_hex(string $s): string {                // рядок PDF у UTF-16BE (для Title/Author)
    $h = 'FEFF';
    foreach (inv_chars($s) as $u) {
        if ($u > 0xFFFF) { $u -= 0x10000; $h .= sprintf('%04X%04X', 0xD800 + ($u >> 10), 0xDC00 + ($u & 0x3FF)); }
        else $h .= sprintf('%04X', $u);
    }
    return '<' . $h . '>';
}
function inv_plural(int $n, string $one, string $few, string $many): string {
    $n = abs($n) % 100;
    if ($n >= 11 && $n <= 14) return $many;
    $d = $n % 10;
    if ($d === 1) return $one;
    if ($d >= 2 && $d <= 4) return $few;
    return $many;
}
function inv_triplet(int $n, bool $fem): string {          // 0..999 → слова
    $h = ['', 'сто', 'двісті', 'триста', 'чотириста', "п'ятсот", 'шістсот', 'сімсот', 'вісімсот', "дев'ятсот"];
    $t = ['', '', 'двадцять', 'тридцять', 'сорок', "п'ятдесят", 'шістдесят', 'сімдесят', 'вісімдесят', "дев'яносто"];
    $teens = ['десять', 'одинадцять', 'дванадцять', 'тринадцять', 'чотирнадцять', "п'ятнадцять", 'шістнадцять', 'сімнадцять', 'вісімнадцять', "дев'ятнадцять"];
    $u = ['', $fem ? 'одна' : 'один', $fem ? 'дві' : 'два', 'три', 'чотири', "п'ять", 'шість', 'сім', 'вісім', "дев'ять"];
    $w = [];
    if ($n >= 100) $w[] = $h[intdiv($n, 100)];
    $r = $n % 100;
    if ($r >= 10 && $r <= 19) $w[] = $teens[$r - 10];
    else { if ($r >= 20) $w[] = $t[intdiv($r, 10)]; if ($r % 10) $w[] = $u[$r % 10]; }
    return implode(' ', $w);
}
function inv_int_words(int $n): string {                    // 0..999 999 999, рід — жіночий (гривня)
    if ($n === 0) return 'нуль';
    $parts = [];
    $mil = intdiv($n, 1000000); $th = intdiv($n % 1000000, 1000); $rest = $n % 1000;
    if ($mil) $parts[] = inv_triplet($mil, false) . ' ' . inv_plural($mil, 'мільйон', 'мільйони', 'мільйонів');
    if ($th)  $parts[] = inv_triplet($th, true) . ' ' . inv_plural($th, 'тисяча', 'тисячі', 'тисяч');
    if ($rest) $parts[] = inv_triplet($rest, true);
    return implode(' ', $parts);
}
function inv_ucfirst(string $s): string {
    if ($s === '' || !preg_match('/^(.)(.*)$/us', $s, $m)) return $s;
    $lo = 'абвгґдеєжзиіїйклмнопрстуфхцчшщьюя'; $up = 'АБВГҐДЕЄЖЗИІЇЙКЛМНОПРСТУФХЦЧШЩЬЮЯ';
    return strtr($m[1], array_combine(preg_split('//u', $lo, -1, PREG_SPLIT_NO_EMPTY), preg_split('//u', $up, -1, PREG_SPLIT_NO_EMPTY))) . $m[2];
}
function inv_amount_words(string $amount): string {         // "233.00" → "Двісті тридцять три гривні 00 копійок"
    [$g, $k] = array_pad(explode('.', $amount, 2), 2, '00');
    $grn = (int)$g; $kop = (int)str_pad(substr($k, 0, 2), 2, '0');
    return inv_ucfirst(inv_int_words($grn) . ' ' . inv_plural($grn, 'гривня', 'гривні', 'гривень')) . ' ' . sprintf('%02d', $kop) . ' ' . inv_plural($kop, 'копійка', 'копійки', 'копійок');
}
function inv_money(string $amount): string {                 // "1234.5" → "1 234,50"
    [$g, $k] = array_pad(explode('.', $amount, 2), 2, '00');
    return number_format((int)$g, 0, '', ' ') . ',' . str_pad(substr($k, 0, 2), 2, '0');
}
function inv_date_uk(DateTimeInterface $d): string {
    $m = ['січня', 'лютого', 'березня', 'квітня', 'травня', 'червня', 'липня', 'серпня', 'вересня', 'жовтня', 'листопада', 'грудня'];
    return (int)$d->format('j') . ' ' . $m[(int)$d->format('n') - 1] . ' ' . $d->format('Y') . ' р.';
}

// ───────────────────────── платіжний QR (формат НБУ BCD/002, як на сторінці) ─────────────────────────
function inv_cp1251(string $s): string {
    $r = @iconv('UTF-8', 'CP1251//TRANSLIT//IGNORE', $s);
    if ($r === false) $r = @mb_convert_encoding($s, 'CP1251', 'UTF-8');
    return $r === false ? '' : $r;
}
function inv_base64url(string $bytes): string { return rtrim(strtr(base64_encode($bytes), '+/', '-_'), '='); }
function inv_qr_amount_payload(string $amount): string {
    [$g, $k] = array_pad(explode('.', $amount, 2), 2, '00');
    return $k === '00' ? (string)(int)$g : (string)(int)$g . '.' . $k;
}
/** Призначення для QR: те саме призначення + посилання на номер/дату рахунку, з урізанням до 140 символів (ліміт стандарту). */
function inv_qr_purpose(string $purpose, int $number, DateTimeInterface $date): string {
    $suffix = ', згідно рахунку № ' . $number . ' від ' . $date->format('d.m.Y');
    $base = trim($purpose);
    // ідемпотентність: якщо призначення вже закінчується цим самим суфіксом (наприклад, при повторному
    // завантаженні рахунку з реєстру, де воно вже збережене з додатком) — не додаємо його вдруге
    if (substr($base, -strlen($suffix)) === $suffix) return $base;
    $max = 140 - mb_strlen($suffix, 'UTF-8');
    if ($max <= 0) return mb_substr(trim($purpose . $suffix), 0, 140, 'UTF-8');
    if (mb_strlen($base, 'UTF-8') > $max) $base = rtrim(mb_substr($base, 0, $max, 'UTF-8'));
    return $base . $suffix;
}
function inv_qr_matrix(array $pay, string $amount, string $purpose): ?array {
    $text = implode("\n", ['BCD', '002', '2', 'UCT', '', (string)($pay['name'] ?? ''), (string)($pay['iban'] ?? ''),
        'UAH' . inv_qr_amount_payload($amount), (string)($pay['tax_id'] ?? ''), '', '', $purpose, '', '']);
    $bytes = inv_cp1251($text);
    if ($bytes === '') return null;
    $url = 'https://bank.gov.ua/qr/' . inv_base64url($bytes);
    try { [$mat, $size] = qr_encode($url, 15); } catch (Throwable $e) { return null; }
    return [$mat, $size];
}

// ───────────────────────── мінімальний PDF-writer ─────────────────────────
class InvPdf {
    const W = 595.28;
    const H = 841.89;
    private $fonts;
    private $ops = [];
    private $logo = null;

    public function __construct(bool $withLogo) {
        $this->fonts = ['F1' => INV_ASSETS['regular'], 'F2' => INV_ASSETS['bold']];
        if ($withLogo) $this->logo = base64_decode(INV_ASSETS['logo']);
    }
    private function gid(string $f, int $u): int {
        $g = $this->fonts[$f]['gid'];
        return $g[$u] ?? $g[32];
    }
    public function width(string $s, string $f, float $size): float {
        $sum = 0;
        foreach (inv_chars($s) as $u) $sum += $this->fonts[$f]['w'][$this->gid($f, $u)];
        return $sum * $size / 1000;
    }
    public function wrap(string $s, string $f, float $size, float $maxW): array {
        $lines = []; $cur = '';
        foreach (preg_split('/\s+/u', trim($s), -1, PREG_SPLIT_NO_EMPTY) as $word) {
            while ($this->width($word, $f, $size) > $maxW) {              // надто довге слово — ріжемо по символах
                $cut = ''; 
                foreach (preg_split('//u', $word, -1, PREG_SPLIT_NO_EMPTY) as $ch) { if ($this->width($cut . $ch, $f, $size) > $maxW) break; $cut .= $ch; }
                if ($cut === '') break;
                if ($cur !== '') { $lines[] = $cur; $cur = ''; }
                $lines[] = $cut; $word = substr($word, strlen($cut));
            }
            $try = $cur === '' ? $word : $cur . ' ' . $word;
            if ($cur !== '' && $this->width($try, $f, $size) > $maxW) { $lines[] = $cur; $cur = $word; } else $cur = $try;
        }
        if ($cur !== '') $lines[] = $cur;
        return $lines ?: [''];
    }
    public function text(float $x, float $y, string $s, string $f, float $size, array $rgb, string $align = 'l', float $boxW = 0.0): void {
        if ($s === '') return;
        $w = $this->width($s, $f, $size);
        if ($align === 'r') $x += $boxW - $w; elseif ($align === 'c') $x += ($boxW - $w) / 2;
        $hex = '';
        foreach (inv_chars($s) as $u) $hex .= sprintf('%04X', $this->gid($f, $u));
        $this->ops[] = sprintf('BT /%s %.2F Tf %.3F %.3F %.3F rg %.2F %.2F Td <%s> Tj ET', $f, $size, $rgb[0], $rgb[1], $rgb[2], $x, self::H - $y, $hex);
    }
    public function rect(float $x, float $y, float $w, float $h, ?array $fill, ?array $stroke = null, float $lw = 0.6, float $r = 0.0): void {
        $yy = self::H - $y - $h; $o = '';
        if ($fill)   $o .= sprintf('%.3F %.3F %.3F rg ', $fill[0], $fill[1], $fill[2]);
        if ($stroke) $o .= sprintf('%.3F %.3F %.3F RG %.2F w ', $stroke[0], $stroke[1], $stroke[2], $lw);
        if ($r > 0) {
            $k = 0.5523 * $r; $x2 = $x + $w; $y2 = $yy + $h;
            $o .= sprintf('%.2F %.2F m %.2F %.2F l %.2F %.2F %.2F %.2F %.2F %.2F c %.2F %.2F l %.2F %.2F %.2F %.2F %.2F %.2F c %.2F %.2F l %.2F %.2F %.2F %.2F %.2F %.2F c %.2F %.2F l %.2F %.2F %.2F %.2F %.2F %.2F c h ',
                $x + $r, $yy, $x2 - $r, $yy, $x2 - $r + $k, $yy, $x2, $yy + $r - $k, $x2, $yy + $r,
                $x2, $y2 - $r, $x2, $y2 - $r + $k, $x2 - $r + $k, $y2, $x2 - $r, $y2,
                $x + $r, $y2, $x + $r - $k, $y2, $x, $y2 - $r + $k, $x, $y2 - $r,
                $x, $yy + $r, $x, $yy + $r - $k, $x + $r - $k, $yy, $x + $r, $yy);
        } else $o .= sprintf('%.2F %.2F %.2F %.2F re ', $x, $yy, $w, $h);
        $o .= $fill && $stroke ? 'B' : ($fill ? 'f' : 'S');
        $this->ops[] = $o;
    }
    public function line(float $x1, float $y1, float $x2, float $y2, array $rgb, float $lw = 0.6): void {
        $this->ops[] = sprintf('%.3F %.3F %.3F RG %.2F w %.2F %.2F m %.2F %.2F l S', $rgb[0], $rgb[1], $rgb[2], $lw, $x1, self::H - $y1, $x2, self::H - $y2);
    }
    public function circle(float $cx, float $cy, float $r, ?array $fill, ?array $stroke = null, float $lw = 0.6): void {
        $k = 0.5523 * $r; $yy = self::H - $cy; $o = '';
        if ($fill)   $o .= sprintf('%.3F %.3F %.3F rg ', $fill[0], $fill[1], $fill[2]);
        if ($stroke) $o .= sprintf('%.3F %.3F %.3F RG %.2F w ', $stroke[0], $stroke[1], $stroke[2], $lw);
        $o .= sprintf('%.2F %.2F m %.2F %.2F %.2F %.2F %.2F %.2F c %.2F %.2F %.2F %.2F %.2F %.2F c %.2F %.2F %.2F %.2F %.2F %.2F c %.2F %.2F %.2F %.2F %.2F %.2F c h ',
            $cx + $r, $yy,
            $cx + $r, $yy + $k, $cx + $k, $yy + $r, $cx, $yy + $r,
            $cx - $k, $yy + $r, $cx - $r, $yy + $k, $cx - $r, $yy,
            $cx - $r, $yy - $k, $cx - $k, $yy - $r, $cx, $yy - $r,
            $cx + $k, $yy - $r, $cx + $r, $yy - $k, $cx + $r, $yy);
        $o .= $fill && $stroke ? 'B' : ($fill ? 'f' : 'S');
        $this->ops[] = $o;
    }
    public function logo(float $x, float $y, float $size): void {
        if ($this->logo !== null) $this->ops[] = sprintf('q %.2F 0 0 %.2F %.2F %.2F cm /Im1 Do Q', $size, $size, $x, self::H - $y - $size);
    }
    /** Малює QR-матрицю (вектором, без растру) у квадраті [x,y,size] з тихою зоною ~3 модулі. */
    public function qr(float $x, float $y, float $size, array $mat, int $n, array $rgb = [0.059, 0.090, 0.165]): void {
        $quiet = 3; $cell = $size / ($n + 2 * $quiet); $yy = self::H - $y - $size;
        $path = '';
        for ($r = 0; $r < $n; $r++) {
            $c = 0;
            while ($c < $n) {
                if (!$mat[$r][$c]) { $c++; continue; }
                $s = $c; while ($c < $n && $mat[$r][$c]) $c++;
                $rx = $x + ($quiet + $s) * $cell; $ry = $yy + $size - ($quiet + $r + 1) * $cell;
                $path .= sprintf('%.3F %.3F %.3F %.3F re ', $rx, $ry, ($c - $s) * $cell, $cell);
            }
        }
        if ($path !== '') $this->ops[] = sprintf('%.3F %.3F %.3F rg %sf', $rgb[0], $rgb[1], $rgb[2], $path);
        // Обов'язковий логотип ₴ у білому колі в центрі (постанова НБУ №97 від 19.08.2025, формати 002/003).
        // Діаметр ≈ 0.3× кількості модулів — та сама пропорція, що й у клієнтському QR на сторінці (index.html);
        // при рівні корекції M/Q (а не L) це лишається в межах запасу надлишковості.
        $cx = $x + $size / 2; $cy = $y + $size / 2; $r = 0.15 * $n * $cell;
        $this->circle($cx, $cy, $r, [1, 1, 1]);
        $u = 8372; // ₴ U+20B4
        $gidF = 'F2';
        $gid = $this->gid($gidF, $u);
        $fs = $r * 1.6;
        $hex = sprintf('%04X', $gid);
        $tw = $this->fonts[$gidF]['w'][$gid] * $fs / 1000;
        // візуальне центрування гліфа по капхайту шрифту, а не по базовій лінії
        $capRatio = $this->fonts[$gidF]['cap'] / 1000;
        $ty = $cy + ($fs * $capRatio) / 2;
        $this->ops[] = sprintf('BT /%s %.2F Tf %.3F %.3F %.3F rg %.2F %.2F Td <%s> Tj ET', $gidF, $fs, $rgb[0], $rgb[1], $rgb[2], $cx - $tw / 2, self::H - $ty, $hex);
    }

    private static function stream(string $dict, string $data, bool $flate = true): string {
        if ($flate && function_exists('gzcompress') && ($z = gzcompress($data, 6)) !== false) { $dict .= ' /Filter /FlateDecode'; $data = $z; }
        return '<< ' . $dict . ' /Length ' . strlen($data) . " >>\nstream\n" . $data . "\nendstream";
    }
    private function fontObjects(string $key, string $psName, int $base, array &$objs): void {
        $f = $this->fonts[$key]; $ttf = base64_decode($f['ttf']);
        $bf = sprintf('%s+%s', $key === 'F1' ? 'CRLTAA' : 'CRLTAB', $psName);
        $widths = implode(' ', $f['w']);
        $objs[$base]     = "<< /Type /Font /Subtype /Type0 /BaseFont /$bf /Encoding /Identity-H /DescendantFonts [" . ($base + 1) . " 0 R] /ToUnicode " . ($base + 4) . " 0 R >>";
        $objs[$base + 1] = "<< /Type /Font /Subtype /CIDFontType2 /BaseFont /$bf /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor " . ($base + 2) . " 0 R /DW 1000 /W [0 [$widths]] /CIDToGIDMap /Identity >>";
        $objs[$base + 2] = sprintf('<< /Type /FontDescriptor /FontName /%s /Flags 4 /FontBBox [%d %d %d %d] /ItalicAngle 0 /Ascent %d /Descent %d /CapHeight %d /StemV %d /FontFile2 %d 0 R >>',
            $bf, $f['bbox'][0], $f['bbox'][1], $f['bbox'][2], $f['bbox'][3], $f['asc'], $f['desc'], $f['cap'], $key === 'F2' ? 140 : 80, $base + 3);
        $objs[$base + 3] = self::stream('/Length1 ' . strlen($ttf), $ttf);
        $pairs = []; foreach ($f['gid'] as $u => $g) $pairs[$g] = $u;                     // gid → unicode
        ksort($pairs);
        $cm = "/CIDInit /ProcSet findresource begin\n12 dict begin\nbegincmap\n/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def\n/CMapName /Adobe-Identity-UCS def\n/CMapType 2 def\n1 begincodespacerange\n<0000> <FFFF>\nendcodespacerange\n";
        foreach (array_chunk($pairs, 100, true) as $chunk) {
            $cm .= count($chunk) . " beginbfchar\n";
            foreach ($chunk as $g => $u) $cm .= sprintf("<%04X> <%04X>\n", $g, $u);
            $cm .= "endbfchar\n";
        }
        $cm .= "endcmap\nCMapName currentdict /CMap defineresource pop\nend\nend";
        $objs[$base + 4] = self::stream('', $cm);
    }
    public function output(array $meta): string {
        $objs = [];
        $content = implode("\n", $this->ops);
        $this->fontObjects('F1', 'Carlito', 6, $objs);
        $this->fontObjects('F2', 'Carlito-Bold', 11, $objs);
        $xo = '';
        if ($this->logo !== null && ($info = @getimagesizefromstring($this->logo)) !== false) {
            $objs[16] = '<< /Type /XObject /Subtype /Image /Width ' . $info[0] . ' /Height ' . $info[1] . ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ' . strlen($this->logo) . " >>\nstream\n" . $this->logo . "\nendstream";
            $xo = ' /XObject << /Im1 16 0 R >>';
        }
        $objs[1] = '<< /Type /Catalog /Pages 2 0 R /Lang (uk-UA) >>';
        $objs[2] = '<< /Type /Pages /Kids [3 0 R] /Count 1 >>';
        $objs[3] = sprintf('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 %.2F %.2F] /Resources << /Font << /F1 6 0 R /F2 11 0 R >>%s >> /Contents 4 0 R >>', self::W, self::H, $xo);
        $objs[4] = self::stream('', $content);
        $objs[5] = '<< /Title ' . inv_utf16_hex($meta['title']) . ' /Author ' . inv_utf16_hex($meta['author']) . ' /Producer (payment-page) /CreationDate (' . $meta['created'] . ') >>';
        ksort($objs);
        $out = "%PDF-1.5\n%\xE2\xE3\xCF\xD3\n"; $off = [];
        foreach ($objs as $n => $body) { $off[$n] = strlen($out); $out .= "$n 0 obj\n$body\nendobj\n"; }
        $max = max(array_keys($objs)); $xref = strlen($out);
        $out .= "xref\n0 " . ($max + 1) . "\n0000000000 65535 f \n";
        for ($i = 1; $i <= $max; $i++) $out .= isset($off[$i]) ? sprintf("%010d 00000 n \n", $off[$i]) : "0000000000 65535 f \n";
        return $out . "trailer\n<< /Size " . ($max + 1) . " /Root 1 0 R /Info 5 0 R >>\nstartxref\n$xref\n%%EOF\n";
    }
}

// ───────────────────────── сам рахунок ─────────────────────────
/** @param array $cfg config.php; @param array $inv ['number'=>int,'date'=>DateTimeInterface,'amount'=>'233.00','purpose'=>string] */
function invoice_build_pdf(array $cfg, array $inv): string {
    $pay  = is_array($cfg['payee'] ?? null) ? $cfg['payee'] : [];
    $conf = is_array($cfg['invoice'] ?? null) ? $cfg['invoice'] : [];
    $p = new InvPdf(($conf['show_logo'] ?? true) !== false);
    $M = 48.0; $W = InvPdf::W; $cw = $W - 2 * $M;
    $ink = [0.059, 0.090, 0.165]; $gray = [0.392, 0.455, 0.545]; $acc = [0.310, 0.275, 0.898];
    $soft = [0.973, 0.980, 0.988]; $rule = [0.886, 0.910, 0.941]; $white = [1, 1, 1];
    $name = (string)($pay['name'] ?? ''); $dateUk = inv_date_uk($inv['date']); $num = (int)$inv['number'];
    // призначення, що фактично йде в оплату (і в QR, і в текст рахунку) — з посиланням на номер і дату рахунку
    $purpose = inv_qr_purpose((string)$inv['purpose'], $num, $inv['date']);

    // шапка
    $p->rect(0, 0, $W, 7, $acc);
    $tx = $M; $hy = 34.0;
    if (($conf['show_logo'] ?? true) !== false) { $p->logo($M, $hy, 56); $tx = $M + 70; }
    $p->text($tx, $hy + 17, $name, 'F2', 15, $ink);
    $p->text($tx, $hy + 34, 'РНОКПП ' . ($pay['tax_id'] ?? ''), 'F1', 10.5, $gray);
    $contact = trim(implode('  ·  ', array_filter([(string)($pay['phone'] ?? ''), (string)($pay['email'] ?? '')])));
    if ($contact !== '') $p->text($tx, $hy + 49, $contact, 'F1', 10.5, $gray);
    $p->line($M, 108, $W - $M, 108, $rule, 0.8);

    // заголовок
    $title = (string)($conf['title'] ?? 'РАХУНОК НА ОПЛАТУ');
    $p->text($M, 142, $title, 'F2', 10.5, $acc);
    $p->text($M, 172, '№ ' . $num . ' від ' . $dateUk, 'F2', 24, $ink);

    // реквізити для оплати
    $labelW = 118.0; $vx = $M + 16 + $labelW; $vw = $cw - 32 - $labelW; $lh = 14.5;
    $rows = [
        ['Платник', $p->wrap((string)($inv['payer'] ?? ''), 'F1', 11, $vw), 'F1'],
        ['Одержувач', [$name], 'F2'],
        ['РНОКПП', [(string)($pay['tax_id'] ?? '')], 'F1'],
        ['IBAN', [trim(chunk_split((string)($pay['iban'] ?? ''), 4, ' '))], 'F2'],
        ['Банк', [(string)($pay['bank'] ?? '')], 'F1'],
        ['МФО / код банку', [trim((string)($pay['mfo'] ?? '') . '  ·  ЄДРПОУ ' . (string)($pay['bank_edrpou'] ?? ''), ' ·')], 'F1'],
    ];
    $rows[] = ['Призначення платежу', $p->wrap($purpose, 'F1', 11, $vw), 'F1'];
    $rows = array_values(array_filter($rows, function ($r) { return trim(implode('', $r[1])) !== ''; }));
    $h = 44.0; foreach ($rows as $r) $h += count($r[1]) * $lh + 7;
    $cy = 200.0;
    $p->rect($M, $cy, $cw, $h, $soft, $rule, 0.8, 8);
    $p->text($M + 16, $cy + 24, 'Реквізити для оплати', 'F2', 11.5, $acc);
    $ry = $cy + 46;
    foreach ($rows as $r) {
        $p->text($M + 16, $ry, $r[0], 'F1', 10, $gray);
        foreach ($r[1] as $i => $ln) $p->text($vx, $ry + $i * $lh, $ln, $r[2], 11, $ink);
        $ry += count($r[1]) * $lh + 7;
    }

    // таблиця
    $y = $cy + $h + 30;
    $wNo = 30.0; $wQty = 54.0; $wPrice = 90.0; $wSum = 90.0; $wName = $cw - $wNo - $wQty - $wPrice - $wSum;
    $xNo = $M; $xName = $xNo + $wNo; $xQty = $xName + $wName; $xPrice = $xQty + $wQty; $xSum = $xPrice + $wPrice;
    $p->rect($M, $y, $cw, 26, $ink, null, 0.6, 6);
    $p->text($xNo, $y + 17, '№', 'F2', 9.5, $white, 'c', $wNo);
    $p->text($xName + 6, $y + 17, 'Найменування', 'F2', 9.5, $white);
    $p->text($xQty, $y + 17, 'К-сть', 'F2', 9.5, $white, 'c', $wQty);
    $p->text($xPrice, $y + 17, 'Ціна, грн', 'F2', 9.5, $white, 'r', $wPrice - 8);
    $p->text($xSum, $y + 17, 'Сума, грн', 'F2', 9.5, $white, 'r', $wSum - 8);
    $lines = $p->wrap($purpose, 'F1', 11, $wName - 12);
    $rh = count($lines) * $lh + 18;
    $ty = $y + 26;
    $p->text($xNo, $ty + 20, '1', 'F1', 11, $ink, 'c', $wNo);
    foreach ($lines as $i => $ln) $p->text($xName + 6, $ty + 20 + $i * $lh, $ln, 'F1', 11, $ink);
    $p->text($xQty, $ty + 20, '1', 'F1', 11, $ink, 'c', $wQty);
    $money = inv_money($inv['amount']);
    $p->text($xPrice, $ty + 20, $money, 'F1', 11, $ink, 'r', $wPrice - 8);
    $p->text($xSum, $ty + 20, $money, 'F1', 11, $ink, 'r', $wSum - 8);
    $p->line($M, $ty + $rh, $W - $M, $ty + $rh, $rule, 0.8);

    // підсумок
    $sy = $ty + $rh + 30;
    $p->text($M, $sy, 'Всього до сплати:', 'F2', 13, $ink);
    $p->text($M, $sy, $money . ' грн', 'F2', 17, $acc, 'r', $cw);
    $wy = $sy + 24;
    foreach ($p->wrap('Сума прописом: ' . inv_amount_words($inv['amount']), 'F1', 11, $cw) as $i => $ln) $p->text($M, $wy + $i * $lh, $ln, 'F1', 11, $gray);
    $ey = $wy + (count($p->wrap('Сума прописом: ' . inv_amount_words($inv['amount']), 'F1', 11, $cw)) - 1) * $lh;
    $note = trim((string)($conf['note'] ?? ''));
    if ($note !== '') { foreach ($p->wrap($note, 'F1', 10, $cw) as $i => $ln) $p->text($M, $ey + 26 + $i * 13, $ln, 'F1', 10, $gray); $ey += 26 + (count($p->wrap($note, 'F1', 10, $cw)) - 1) * 13; }

    // QR для оплати (той самий формат НБУ, що на сторінці; те саме призначення, що показане вище)
    $qr = inv_qr_matrix($pay, $inv['amount'], $purpose);
    $qrSize = 100.0;                                       // ~35 мм — з запасом для впевненого сканування (65+ модулів)

    // підпис
    $gy = $ey + ($qr ? 78 : 62);
    $sigW = $qr ? $cw - $qrSize - 28 : $cw;
    $p->text($M, $gy, 'Виконавець', 'F1', 10.5, $gray);
    $p->line($M + 70, $gy + 2, min($M + 250, $M + $sigW), $gy + 2, $ink, 0.7);
    $p->text($M + 70, $gy + 15, $name, 'F1', 9, $gray);
    if ($qr) {
        [$mat, $n] = $qr;
        $qx = $W - $M - $qrSize; $qy = $gy - 48;
        $p->rect($qx - 8, $qy - 8, $qrSize + 16, $qrSize + 34, $white, $rule, 0.8, 8);
        $p->qr($qx, $qy, $qrSize, $mat, $n, $ink);
        $p->text($qx - 8, $qy + $qrSize + 18, 'Скануйте для оплати', 'F1', 8, $gray, 'c', $qrSize + 16);
    }

    $tz = $inv['date']->format('O'); $tzs = substr($tz, 0, 3) . "'" . substr($tz, 3, 2) . "'";
    return $p->output(['title' => 'Рахунок № ' . $num . ' від ' . $dateUk, 'author' => $name, 'created' => 'D:' . $inv['date']->format('YmdHis') . $tzs]);
}
